365: // Run ready tasks
366: void ThreadUtility::priv_data::doPeriodicTasks()
367: {
368: 	while (!this->terminated.load())
369: 	{
370: 		auto currentTime = std::chrono::system_clock::now();
371: 		TimePoint nextOperationTime = currentTime + this->maxDelay;
372: 
373: 		// Run each due task with job_mutex released, so a long-running callback
374: 		// (e.g. a reconnect blocked on network I/O) does not stall removePeriodicTask()
375: 		while (true)
376: 		{
377: 			std::function<void()> taskCallback;
378: 			LogString taskName;
379: 			Period taskDelay;
380: 			bool foundTask = false;
381: 
382: 			// Take a copy of the next due task while holding the lock
383: 			{
384: 				if (this->terminated.load())
385: 					return;
386: 				std::lock_guard<std::recursive_mutex> lock(this->job_mutex);
387: 				auto pItem = std::find_if(this->jobs.begin(), this->jobs.end()
388: 					, [currentTime](const NamedPeriodicFunction& item)
389: 					{ return !item.removed && item.nextRun <= currentTime; }
390: 					);
391: 				if (pItem != this->jobs.end())
392: 				{
393: 					taskCallback = pItem->f;
394: 					taskName = pItem->name;
395: 					taskDelay = pItem->delay;
396: 					foundTask = true;
397: 				}
398: 			}
399: 
400: 			// No more tasks are due, leave the loop
401: 			if (!foundTask)
402: 			{
403: 				break;
404: 			}
405: 
406: 			// Execute the callback outside the lock
407: 			bool success = false;
408: 			try
409: 			{
410: 				taskCallback();
411: 				success = true;
412: 			}
413: 			catch (std::exception& ex)
414: 			{
415: 				LogLog::warn(taskName, ex);
416: 			}
417: 			catch (...)
418: 			{
419: 				LogLog::warn(taskName + LOG4CXX_STR(" threw an exception"));
420: 			}
421: 
422: 			// Re-find the task (it may have been removed while running) and reschedule it
423: 			{
424: 				std::lock_guard<std::recursive_mutex> lock(this->job_mutex);
425: 				auto pItem = std::find_if(this->jobs.begin(), this->jobs.end()
426: 					, [&taskName](const NamedPeriodicFunction& item)
427: 					{ return !item.removed && taskName == item.name; }
428: 					);
429: 
430: 				if (pItem != this->jobs.end())
431: 				{
432: 					// Always push nextRun out, so a failing task waits before the next retry
433: 					pItem->nextRun = std::chrono::system_clock::now() + taskDelay;
434: 					if (success)
435: 						pItem->errorCount = 0;
436: 					else
437: 						++pItem->errorCount;
438: 				}
439: 			}
440: 		}
441: 
442: 		// Update nextOperationTime under the lock
443: 		{
444: 			std::lock_guard<std::recursive_mutex> lock(this->job_mutex);
445: 			for (const auto& item : this->jobs)
446: 			{
447: 				if (!item.removed && item.nextRun < nextOperationTime)
448: 				{
449: 					nextOperationTime = item.nextRun;
450: 				}
451: 			}
452: 		}
453: 
454: 		// Delete removed and faulty tasks
455: 		while (1)
456: 		{
457: 			std::lock_guard<std::recursive_mutex> lock(this->job_mutex);
458: 			auto pItem = std::find_if(this->jobs.begin(), this->jobs.end()
459: 				, [this](const NamedPeriodicFunction& item)
460: 				{ return item.removed || this->retryCount < item.errorCount; }
461: 				);
462: 			if (this->jobs.end() == pItem)
463: 				break;
464: 			LOGLOG_DEBUG(this->log, LOG4CXX_STR("doPeriodicTasks: erase ") << pItem->name);
465: 			this->jobs.erase(pItem);
466: 			if (this->jobs.empty())
467: 				return;
468: 		}
469: 
470: 		// Wait until the next task is due or an add/remove/shutdown wakes us
471: 		std::unique_lock<std::mutex> lock(this->interrupt_mutex);
472: 		this->interrupt.wait_until(lock, nextOperationTime);
473: 	}
474: }
